import java.util.Scanner;

public class Table {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());
        for (int i = 1; i <= 12; i++) System.out.println(n + " x " + i + " = " + n * i);
    }
}

