}

exercises.solution:
public class Vowels {
    public static int countVowels(String text) {
        int n = 0;
        for (char c : text.toLowerCase().toCharArray()) {
            if ("aeiou".indexOf(c) >= 0) n++;
        }
        return n;
    }
}

